import {availableBlueprints,bestRecommendation,evaluateArchetype,adventureInsights,archetypeRelevant,usablePower} from '../recommendations.e0c600d8e1e5.mjs';
import {powerLabel,powerIcon,heroIcon} from './icons.fc9f2b44a4f9.mjs';
const node=(tag,cls,text)=>{const el=document.createElement(tag);el.className=cls;if(text!==undefined)el.textContent=text;return el;};
export function selectionState(ids,level){const unique=[...new Set(ids)],capacity=Math.max(0,Math.floor(level));return {capacity,active:unique.slice(0,capacity),inactive:unique.slice(capacity)};}
export function renderSelectionPlanner({heroRecord,idealSummary,mySummary,idealContainer,myContainer,tableContainer,heroId,powers,bundle,blueprintId,selectedIds,projection,mode,onToggle,onRecommended,onClear}){
 const state=selectionState(selectedIds,8),b=availableBlueprints(bundle?.blueprints||[],powers,heroId,mode).find(b=>b.id===blueprintId);
 const engine=b?bestRecommendation({blueprint:b,powers,rules:bundle.rules,mode,horizon:8}):null;
 idealContainer.replaceChildren();myContainer.replaceChildren();idealContainer.hidden=!engine;if(idealSummary)idealSummary.hidden=!engine;const area=document.getElementById('chaosArea');if(area)area.className='panel chaos-area'+(engine?'':' adventure-mode');
 const ideal=node('div','compact-fit-row');ideal.append(node('h3','',b?'Perfect Blueprint Fit - '+(b.category||b.archetype).toUpperCase():'Your Adventure'),node('strong','fit-score',engine?`${engine.fit.score}/100`:''));
 const guidance=node('p','mini-note',engine?`Ideal Level 8 reference: highest score among ${engine.evaluated} authored eligible combinations. Perfect names the reference, not a guaranteed 100 or win rate.`:'No prescribed pathway. Choose any eligible powers; the score tracks explicit synergy rules only.');idealContainer.append(ideal,guidance);if(engine){const math=node('details','compact-score-explanation');math.append(node('summary','','Ideal score calculation'),node('p','',`${engine.fit.targetPoints.toFixed(1)}/50 target coverage + ${engine.fit.compatibilityPoints.toFixed(1)}/35 role compatibility + ${engine.fit.interactionPoints} explicit interaction points. Rounded and clamped to 0-100. Fully eligible authored combinations only; this is a limited search, not a proof of global optimality.`));idealContainer.append(math);}
 const map=new Map(powers.map(p=>[p.id,p]));
 function pickStrip(ids,player=false){const strip=node('ol','numbered-picks'+(player?' player-picks':' ideal-picks'));strip.setAttribute('aria-label',player?'Your stored power picks':'Ideal Level 8 picks');const count=Math.max(8,ids.length);for(let i=0;i<count;i++){const p=map.get(ids[i]),slot=node('li','numbered-pick'+(player&&i>=state.capacity?' inactive-pick':''));const button=node('button','pick-button');button.type='button';button.title=p?`${i+1}. ${p.name} (${p.rarity})${player&&i>=state.capacity?' - temporarily inactive':''}`:`Pick ${i+1}: empty`;button.setAttribute('aria-label',button.title);button.append(node('span','pick-number',String(i+1)));if(p){button.append(powerIcon(p,28));button.onclick=()=>{const panel=document.getElementById('powerDetailPanel');if(!panel)return;panel.replaceChildren();panel.hidden=false;const close=node('button','detail-close','Close');close.onclick=()=>{panel.hidden=true;};panel.append(close,powerLabel(p),node('p','',p.description));};}else{button.append(node('span','empty-pick','+'));button.disabled=true;}slot.append(button);strip.append(slot);}return strip;}
 function powerInfo(ids,player=false){const table=node('table','ideal-power-info'+(player?' selected-power-info':''));table.append(node('caption','',player?'Your selected powers':'Recommended Level 8 powers'));const body=node('tbody','');for(const [i,id] of ids.entries()){const p=map.get(id);if(!p)continue;const row=node('tr',player&&i>=state.capacity?'inactive-pick':'');row.append(node('td','',String(i+1)),node('td','ideal-power-name',p.name),node('td','rarity-'+(p.rarity||'unknown').toLowerCase(),p.rarity||'Unknown'));const effect=node('td','',p.description.length>95?p.description.slice(0,92)+'...':p.description);effect.title=p.description;row.append(effect);body.append(row);}if(player&&!ids.length){const row=node('tr','empty-build-row'),cell=node('td','','Choose talents below to create your build.');cell.colSpan=4;row.append(cell);body.append(row);}table.append(body);return table;}
 if(engine)idealContainer.append(pickStrip(engine.ids),powerInfo(engine.ids));

 let score=null,explanation='';
 if(b){const fit=evaluateArchetype({blueprint:b,powers,selectedIds:state.active,rules:bundle.rules,mode});score=fit.score;explanation=`${fit.targetPoints.toFixed(1)}/50 coverage + ${fit.compatibilityPoints.toFixed(1)}/35 role compatibility + ${fit.interactionPoints} explicit interaction points. Inactive powers do not count.`;}
 else{const insight=adventureInsights({powers,heroId,selectedIds:state.active,rules:bundle?.rules||[],mode});const relevant=(bundle?.rules||[]).filter(r=>r.heroId===heroId&&(mode==='experimental'||r.verificationStatus==='verified'));const possible=relevant.reduce((n,r)=>n+Math.max(0,r.weight),0),earned=insight.interactions.reduce((n,r)=>n+r.weight,0);score=possible?Math.max(0,Math.min(100,Math.round(100*earned/possible))):0;explanation=`Overall synergy: ${earned} matched interaction points / ${possible} positive rule points for this hero. Shared-ability clues earn no bonus. No matching rule does not establish a bad build.`;}
 const mine=node('div','compact-fit-row');mine.append(node('h3','','My Build Fit'),node('strong','fit-score',!selectedIds.length?'Not started':!state.active.length?'No active powers':`${score}/100`));myContainer.append(mine,node('p','selection-capacity',`${state.active.length}/8 talent slots used${state.inactive.length?`; ${state.inactive.length} saved picks exceed the eight-slot limit`:''}.`));const details=node('details','compact-score-explanation');details.append(node('summary','','Calculation and synergy assumptions'),node('p','',explanation));myContainer.append(details,pickStrip(selectedIds,true),powerInfo(selectedIds,true));
 if(!tableContainer.searchControl){
  const tools=node('div','selection-tools'),search=node('input','');search.type='search';search.placeholder='Search eligible powers';search.setAttribute('aria-label','Search selectable powers');tools.append(search);const use=node('button','primary','Use Recommended Blueprint'),clear=node('button','','Clear My Build');tools.append(use,clear);const notice=node('p','mini-note');const scroll=node('div','power-table-scroll');const table=node('div','power-selection-grid');scroll.append(table);tableContainer.append(tools,notice,scroll);tableContainer.searchControl=search;tableContainer.useControl=use;tableContainer.clearControl=clear;tableContainer.notice=notice;tableContainer.table=table;tableContainer.listScroll=scroll;
 }
 const context=heroId+'|'+blueprintId;if(tableContainer.context!==context){tableContainer.listScroll.scrollTop=0;tableContainer.context=context;}
 tableContainer.useControl.hidden=!engine;tableContainer.useControl.disabled=!engine||state.capacity===0;tableContainer.useControl.onclick=()=>onRecommended(engine.ids.slice(0,state.capacity));tableContainer.clearControl.onclick=onClear;
 tableContainer.notice.textContent=mode==='verified'?'Verified eligible powers only. This catalog may have no fully verified records.':'Community eligible powers are partially verified, not independently verified. Strict verified-only mode is available in build settings.';
 if(idealSummary&&mySummary){
 function summary(host,title,ids,player){host.replaceChildren();const heading=node('h3','summary-hero');heading.append(heroIcon(heroId),node('span','',heroRecord?.name||'Selected hero'));host.append(heading,node('p','summary-label',title),node('p','',`${heroRecord?.role||'Role unconfirmed'} / ${ids.length} ${player?'active picks':'ideal targets'}`));const legendary=ids.filter(id=>map.get(id)?.rarity==='Legendary').length;host.append(node('p','mini-note',`${legendary} Legendary ${legendary===1?'power':'powers'}${player?` / ${state.inactive.length} inactive`:''}`));if(player){host.append(node('p','mini-note',state.active.length?'Your choices are scored against '+(b?.archetype||'explicit synergy rules')+'.':'Choose talents from the table to start your build.'));const list=node('ul','summary-power-list');for(const id of ids){const p=map.get(id);if(p)list.append(node('li','',p.name));}host.append(list);}else host.append(node('p','mini-note',b?.strategy||'Free selection with no imposed pathway.'));}
 summary(idealSummary,'Engine reference',engine?.ids||[],false);summary(mySummary,b?'Your '+(b.category||b.archetype).toUpperCase()+' build':'Your Adventure',state.active,true);idealContainer.append(idealSummary);myContainer.append(mySummary);
 }
 const rows=powers.filter(p=>usablePower(p,heroId,mode)&&(!b||archetypeRelevant(p,b,powers,mode)||selectedIds.includes(p.id)));tableContainer.searchControl.placeholder=b?'Search '+(b.category||b.archetype)+' powers':'Search eligible powers';
 if(b)rows.sort((a,c)=>{const fit=p=>evaluateArchetype({blueprint:b,powers,selectedIds:[p.id],rules:[],mode});const aFit=fit(a),cFit=fit(c);return cFit.compatibilityPoints-aFit.compatibilityPoints||cFit.score-aFit.score||a.name.localeCompare(c.name);});else rows.sort((a,b)=>a.name.localeCompare(b.name));
 const draw=()=>{const grid=tableContainer.table;grid.replaceChildren();const q=tableContainer.searchControl.value.toLowerCase(),matches=rows.filter(p=>(p.name+' '+p.description+' '+p.rarity).toLowerCase().includes(q));for(const p of matches){const chosen=selectedIds.includes(p.id),inactive=state.inactive.includes(p.id),recommended=engine?.ids.includes(p.id);const card=node('article','talent-choice'+(inactive?' temporarily-inactive':chosen?' player-selected':''));const control=node('input','');control.type='checkbox';control.checked=chosen;control.disabled=!chosen&&selectedIds.length>=state.capacity;control.setAttribute('aria-label',`${chosen?'Remove':'Select'} ${p.name}`);control.dataset.powerId=p.id;control.onchange=()=>onToggle(p.id);const label=node('label','talent-choice-heading');label.append(control,powerLabel(p));card.append(label,node('p','talent-effect',p.description.length>110?p.description.slice(0,107)+'...':p.description));card.append(node('p','talent-metadata',`${p.rarity||'Unknown rarity'}${p.provenance?.section==='General Powers'?' / Shared power':''} / ${p.verificationStatus?.replaceAll('_',' ')||'Unreviewed'} / ${recommended?'Ideal #'+(engine.ids.indexOf(p.id)+1):'Outside ideal'}${chosen?' / '+(inactive?'Inactive':'Selected'):''}`));card.title=`${p.description} ? ${p.rarity||'Unknown rarity'} / ${p.verificationStatus?.replaceAll('_',' ')||'Unreviewed'}${p.provenance?.section==='General Powers'?' / Shared power':''} / ${recommended?'Ideal #'+(engine.ids.indexOf(p.id)+1):'Outside ideal'}${chosen?' / Selected':''}`;const details=node('button','power-info','Info');details.setAttribute('aria-label','Full effect and metadata for '+p.name);details.onclick=()=>{const panel=document.getElementById('powerDetailPanel');if(!panel)return;panel.replaceChildren();panel.hidden=false;const close=node('button','detail-close','Close');close.onclick=()=>{panel.hidden=true;};panel.append(close,powerLabel(p),node('p','',p.description),node('p','',`Rarity: ${p.rarity||'Unknown'}; verification: ${p.verificationStatus}; ${recommended?'Recommended blueprint power':'Outside recommended blueprint'}; Eligibility: ${p.eligibilityStatus}; availability: ${p.availability}; source: ${p.provenance?.section||'Unknown'}.`));if(p.sourceUrl){const source=node('a','','Power source');source.href=p.sourceUrl;source.target='_blank';source.rel='noopener noreferrer';panel.append(source);}};card.append(details);grid.append(card);}if(!matches.length)grid.append(node('p','empty','No eligible powers match this evidence mode and search.'));};tableContainer.searchControl.oninput=draw;draw();
}
